// 送回人只知道本人携带与返报；写回书者看不到远方收取/取消，原sender要实际收到才获新知情。
#include "task_message_return_view.hpp"
namespace hanmo::resident {namespace {
using V=BoundaryValue;
StableId label(const StableId& stage){if(stage=="awaiting_reply")return "去程已交，等待原收件者托回书";if(stage=="collecting")return "正在当面接回书";if(stage=="collection_interrupted")return "接回书未完成，原任务仍待办理";if(stage=="carrying_reply")return "原回书已接到，待向原发信人交回";if(stage=="reply_not_in_own_bag")return "本人携带物中未见原回书";if(stage=="reporting")return "正在交回原回书";if(stage=="report_interrupted")return "交回未完成，原任务仍待办理";if(stage=="returned")return "已当面交回并按原任务结酬";if(stage=="received_return")return "已当面收到原回书";if(stage=="entrusted")return "已当面托付回书";if(stage=="cancelled")return "已按原任务办理取消与实物返还";return stage;}
BoundaryValue identity(const WorldIdentity& id){StableId world;const char* hex="0123456789abcdef";for(auto byte:id.world_id){world.push_back(hex[byte>>4]);world.push_back(hex[byte&15]);}return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{id.execution_epoch}},{"revision",V{id.revision}},{"tick",V{id.tick}}});}
}
static Outcome<std::optional<TaskMessageReturnKnownSource>> project_known_return(const TaskMessageReturnSources& x,const StableId& observer,const StableId& task_id){if(x.phase)return {false,{},common_failure("TaskMessageReturnStableQueryRequired").error};if(!x.common.actor(observer))return {false,{},common_failure("UnknownMessageObserver").error};const auto* task=x.tasks.tasks.find(task_id);const auto* policy=task?task_message_return_policy(x.catalog,task->offer_id):nullptr;if(!task||!policy)return {true,std::nullopt,{}};const TaskMessageHandoff* outbound=nullptr;for(const auto& row:x.messages.receipts.rows())if(row.second.task_id==task_id)outbound=&row.second;const TaskMessageReturnDelivery* delivery=nullptr;for(const auto& row:x.state.deliveries.rows())if(row.second.task_id==task_id)delivery=&row.second;const auto* original=x.task_catalog.offers.find(task->offer_id);const bool carrier=observer==task->assignee;const bool recipient=outbound&&observer==outbound->recipient_actor_id;const bool sender=original&&observer==original->issuer.id&&delivery;if(!outbound||(!carrier&&!recipient&&!sender))return {true,std::nullopt,{}};TaskMessageReturnKnownSource out;out.source_identity=x.common.state().identity;out.observer_actor_id=observer;out.task_id=task_id;out.policy_id=policy->id;out.carrier_actor_id=task->assignee;out.other_actor_id=carrier?outbound->recipient_actor_id:task->assignee;out.reply_item_id=policy->reply_item_id;out.source_fact_id=outbound->fact_id;out.known_place_id=outbound->place_id;out.observed_tick=outbound->tick;out.stage="awaiting_reply";
 if(sender){const auto& report=*x.messages.reports.find(delivery->report_fact_id);out.source_fact_id=delivery->fact_id;out.known_place_id=report.place_id;out.observed_tick=delivery->tick;out.stage="received_return";return {true,std::move(out),{}};}
 const TaskMessageReturnStart* start=nullptr;for(const auto& row:x.state.starts.rows())if(row.second.task_id==task_id)start=&row.second;if(start){out.source_fact_id=start->fact_id;out.observed_tick=start->started_tick;out.known_place_id=start->context.place_id;out.stage="collecting";for(const auto& row:x.state.collections.rows())if(row.second.start_fact_id==start->fact_id){out.source_fact_id=row.first;out.observed_tick=row.second.tick;out.stage=row.second.success?(carrier?"carrying_reply":"entrusted"):"collection_interrupted";if(carrier&&row.second.success){const auto* bag=x.common.inventory(start->carrier_inventory_id);bool carrying=false;if(bag)for(const auto& lot:bag->lots)if(lot.id==row.second.reply_lot_id&&lot.item_id==policy->reply_item_id&&lot.quantity==1&&owner_equal(lot.owner,Owner{Owner::Kind::task,task_id,{}}))carrying=true;if(!carrying)out.stage="reply_not_in_own_bag";}}}
 // 原收件者到此即止；不得用任务现在的success/cancelled告诉他远方返回结果。
 if(!carrier)return {true,std::move(out),{}};
 const TaskMessageReturnReportStart* reporting=nullptr;for(const auto& row:x.state.report_starts.rows())if(row.second.task_id==task_id)reporting=&row.second;if(reporting){out.other_actor_id=reporting->sender_actor_id;out.known_place_id=reporting->context.place_id;out.source_fact_id=reporting->fact_id;out.observed_tick=reporting->started_tick;out.stage="reporting";for(const auto& row:x.state.report_interruptions.rows())if(row.second.report_start_fact_id==reporting->fact_id){out.source_fact_id=row.first;out.observed_tick=row.second.tick;out.stage="report_interrupted";}}
 if(delivery){const auto& report=*x.messages.reports.find(delivery->report_fact_id);out.source_fact_id=delivery->fact_id;out.known_place_id=report.place_id;out.observed_tick=delivery->tick;out.stage="returned";}
 if(task->status=="cancelled"||task->status=="failed")for(const auto& row:x.assets.receipts.rows())if(row.second.task_id==task_id&&row.second.stage=="cancellation_return"){out.source_fact_id=row.first;out.observed_tick=row.second.tick;out.stage="cancelled";out.other_actor_id=original->issuer.id;out.known_place_id.clear();}
 return {true,std::move(out),{}};
}
Outcome<std::optional<TaskMessageReturnKnownSource>> TaskMessageReturnAccess::known_task_message_return(const StableId& observer,const StableId& task_id)const{auto valid=validate_task_message_returns(sources_);if(!valid.ok)return {false,{},valid.error};return project_known_return(sources_,observer,task_id);}
Outcome<BoundaryValue> query_task_message_returns(const TaskMessageReturnSources& x,const InteractionState& interaction,const InteractionAccess& access,Integer cursor){if(x.phase)return {false,{},common_failure("TaskMessageReturnStableQueryRequired").error};const auto& observer=x.common.state().metadata.player_actor_id;if(!x.common.actor(observer))return {false,{},common_failure("UnknownPlayer").error};auto valid=validate_task_message_returns(x);if(!valid.ok)return {false,{},valid.error};std::vector<TaskMessageReturnKnownSource> known;for(auto i=x.tasks.tasks.rows().rbegin();i!=x.tasks.tasks.rows().rend();++i){auto row=project_known_return(x,observer,i->first);if(!row.ok)return {false,{},row.error};if(row.value)known.push_back(std::move(*row.value));}if(cursor<0||static_cast<std::size_t>(cursor)>known.size())return {false,{},common_failure("InvalidTaskMessageReturnCursor").error};V::Array rows;Integer next=cursor;for(;static_cast<std::size_t>(next)<known.size()&&rows.size()<16;++next){const auto& row=known[static_cast<std::size_t>(next)];const auto& task=*x.tasks.tasks.find(row.task_id);const auto& original=*x.task_catalog.offers.find(task.offer_id);V::Array actions;if(observer==row.carrier_actor_id&&(row.stage=="awaiting_reply"||row.stage=="collection_interrupted")){auto quote=preview_task_message_return_collection(x,interaction,access,observer,{row.task_id});actions.push_back(boundary::obj({{"command",V{StableId{task_message_return_collect_command}}},{"params",boundary::obj({{"task_id",V{row.task_id}}})},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}},{"text",V{StableId{"当面接回书"}}},{"summary",V{StableId{"占用双方一半日；完成时仍须原收件者在场，并实际取得原任务产权的回书。"}}}}));}
 rows.push_back(boundary::obj({{"id",V{row.task_id}},{"task_id",V{row.task_id}},{"display_name",V{original.display_name}},{"source_fact_id",V{row.source_fact_id}},{"stage",V{row.stage}},{"status_text",V{label(row.stage)}},{"observed_tick",V{row.observed_tick}},{"known_place_id",V{row.known_place_id}},{"terms_text",V{StableId{"回书仍属原任务；须带回原件向原发信人当面返报，报酬与取消沿原委托办理。"}}},{"actions",V{std::move(actions)}}}));}
 V::Dict result{{"ok",V{true}},{"enabled",V{true}},{"observer_actor_id",V{observer}},{"source_identity",identity(x.common.state().identity)},{"cursor",V{cursor}},{"rows",V{std::move(rows)}}};if(static_cast<std::size_t>(next)<known.size())result.emplace_back("next_cursor",V{next});return {true,V{std::move(result)},{}};
}
}
